/**
 * ZagBench – BeFannkuch (Java port of BeFannkuch.class.st).
 *
 * Fannkuch-Redux: count pancake flips across all permutations of 0..n-1.
 * Permutations generated by the rotation-based algorithm (Benchmark Game
 * reference) so that checksum signs alternate correctly with permutation order.
 * No java.util.* imports.
 */
public class BeFannkuch extends Benchmark {

    @Override public int mainIterations()  { return 2; }
    @Override public int innerIterations() { return 10; }

    // Verification table (checkSum, maxFlips) for n = 1..11
    private static final int[][] EXPECTED = {
        {      0,  0},  // n=1
        {     -1,  1},  // n=2
        {      2,  2},  // n=3
        {      4,  4},  // n=4
        {     11,  7},  // n=5
        {     49, 10},  // n=6
        {    228, 16},  // n=7
        {   1616, 22},  // n=8
        {   8629, 30},  // n=9
        {  73196, 38},  // n=10
        {556355, 51},  // n=11
    };

    @Override
    public boolean innerBenchmarkLoop(int iterations) {
        int[] result = solve(iterations);
        return verify(result, iterations);
    }

    // -----------------------------------------------------------------------
    // Core algorithm
    // -----------------------------------------------------------------------

    private int[] solve(int n) {
        // Rotation-based generator (Benchmark Game reference order); the
        // alternating checksum sign depends on this exact permutation order.
        int[] perm1    = new int[n];
        int[] count    = new int[n];
        int[] perm     = new int[n];
        int   maxCount = 0;
        int   checkSum = 0;
        int   nperm    = 0;
        for (int i = 0; i < n; i++) { perm1[i] = i; count[i] = i + 1; }

        while (true) {
            int flips = 0;
            if (perm1[0] != 0) {
                for (int i = 0; i < n; i++) perm[i] = perm1[i];
                while (perm[0] != 0) {
                    int lo = 0, hi = perm[0];
                    while (lo < hi) { int t = perm[lo]; perm[lo] = perm[hi]; perm[hi] = t; lo++; hi--; }
                    flips++;
                }
                if (flips > maxCount) maxCount = flips;
            }
            checkSum += (nperm % 2 == 0) ? flips : -flips;
            nperm++;

            int r = 1;
            while (true) {
                if (r >= n) return new int[]{checkSum, maxCount};
                int perm0 = perm1[0];
                for (int i = 0; i < r; i++) perm1[i] = perm1[i + 1];
                perm1[r] = perm0;
                if (--count[r] > 0) break;
                count[r] = r + 1;
                r++;
            }
        }
    }

    private boolean verify(int[] result, int n) {
        if (n < 1 || n > 11) {
            System.out.println("No verification result for " + n + " found");
            return false;
        }
        return result[0] == EXPECTED[n - 1][0] && result[1] == EXPECTED[n - 1][1];
    }
}
